mapper.select:
SELECT c.`id`, c.`name`, c.`user_id`, c.`ROW`, c.`col`, c.`create_time` FROM `security_device_auth` a INNER JOIN `multiple_video_collect_camera` b ON a.`security_device_id` = b.`device_id` INNER JOIN `multiple_video_collect` c ON b.`multiple_video_collect_id` = c.`id` where a.`user_id`=#{userId} AND c.`user_id` = #{userId}
and c.`name` like concat('%',#{param.keyword},'%')
group by c.`id` order by c.`create_time` desc
